CREATE COLUMN TABLE "UAT_JBF2"."OUDP" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Remarks" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "Father" NVARCHAR(20), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OUDP_NAME" ON "UAT_JBF2"."OUDP" ( "Name" ASC )